            password = password.strip()
            if password and test_password(zip_path, password, file_number):
                return password
    return None


def format_time(elapsed: float) -> str:
    """Format elapsed time as ms us ns."""
    ms = int(elapsed * 1000)
    us = int((elapsed * 1000000) % 1000)
    ns = int((elapsed * 1000000000) % 1000)
    return f'{ms}ms {us}us {ns}ns'


