#!/usr/bin/env python3
"""zip-password-finder - Find the password of protected ZIP files"""

import argparse
import sys
import os
import time
import zipfile
from itertools import product

# Character sets
CHARSETS = {
    'l': 'abcdefghijklmnopqrstuvwxyz',
    'u': 'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
    'd': '0123456789',
    'h': '0123456789abcdef',
    'H': '0123456789ABCDEF',
    's': ' \"\'!#$%&()*+,-./:;<=>?@[\\]^_`{|}~'
}

def combine_charsets(charset_str):
    """Combine multiple character sets into one."""
    combined = ''
    for char in charset_str:
        if char in CHARSETS:
            combined += CHARSETS[char]
    return combined

def generate_passwords(charset, min_len, max_len, starting_password=None):
    """Generate passwords based on charset and length range."""
    if starting_password:
        # First try the starting password itself
        yield starting_password
        # Then continue with normal generation from min_len to max_len
        for length in range(min_len, max_len + 1):
            for combo in product(charset, repeat=length):
                yield ''.join(combo)
    else:
