                filename = f'file{file_number}.txt'
                if filename in zf.namelist():
                    zf.extract(filename, path='/tmp')
                else:
                    # Try to extract any encrypted file
                    for name in zf.namelist():
                        try:
                            zf.extract(name, path='/tmp')
                            # Check if extraction actually worked
                            if os.path.exists(f'/tmp/{name}'):
                                return True
                        except:
                            continue
            else:
                zf.extractall(path='/tmp')
            return True
    except zipfile.BadZipFile:
        return False
    except Exception:
        return False

def find_password_bruteforce(zip_path, charset, min_len, max_len, file_number=0):
    """Find password using brute force."""
    for password in generate_passwords(charset, min_len, max_len):
        if test_password(zip_path, password, file_number):
            return password
    return None

def main():
    parser = argparse.ArgumentParser(
        description='Find the password of protected ZIP files',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog='''
Examples:
  zip-password-finder --inputFile secret.zip --passwordDictionary words.txt
  zip-password-finder --inputFile secret.zip --charset l --minPasswordLen 1 --maxPasswordLen 6
'''
    )
    parser.add_argument('-i', '--inputFile', required=True, help='path to zip input file')
    parser.add_argument('-w', '--workers', type=int, default=1, help='number of workers')
    parser.add_argument('-p', '--passwordDictionary', help='path to a password dictionary file')
    parser.add_argument('-c', '--charset', default='lud', help='charset to use to generate password [default: lud]')
    parser.add_argument('--charsetFile', help='path to a charset file')
    parser.add_argument('--minPasswordLen', type=int, default=1, help='minimum password length [default: 1]')
    parser.add_argument('--maxPasswordLen', type=int, default=10, help='maximum password length [default: 10]')
    parser.add_argument('--fileNumber', type=int, default=0, help='file number in the zip archive [default: 0]')
    parser.add_argument('-s', '--startingPassword', help='password to start from')
    parser.add_argument('-V', '--version', action='version', version='zip-password-finder 0.10.3')

    args = parser.parse_args()

    # Validate input file
    if not os.path.exists(args.inputFile):
        print(f'CLI argument error - "{args.inputFile}" does not exist')
        sys.exit(1)

    # Validate charset
    if args.charsetFile:
        if not os.path.exists(args.charsetFile):
            print(f'CLI argument error - "{args.charsetFile}" does not exist')
            sys.exit(1)
        with open(args.charsetFile, 'r') as f:
            charset = f.read().strip()
    else:
        # Check if charset is a single valid key or needs combining
        if args.charset in CHARSETS:
            charset = CHARSETS[args.charset]
        else:
            # Combine multiple charsets
            charset = combine_charsets(args.charset)
            if not charset:
                print(f'CLI argument error - "{args.charset}" is not a valid charset')
                sys.exit(1)

    # Validate starting password - check if all characters are in the charset
    if args.startingPassword:
        for char in args.startingPassword:
            if char not in charset:
                print(f'CLI argument error - "{args.startingPassword}" uses characters out of the generation charset')
                sys.exit(1)

    # Validate min/max password length
    if args.minPasswordLen > args.maxPasswordLen:
        print(f'CLI argument error - minPasswordLen ({args.minPasswordLen}) cannot be greater than maxPasswordLen ({args.maxPasswordLen})')
        sys.exit(1)

    # Validate workers
    if args.workers < 1:
        print(f'CLI argument error - workers must be at least 1')
        sys.exit(1)

    start_time = time.time()

    # Try dictionary attack first
    if args.passwordDictionary:
        if not os.path.exists(args.passwordDictionary):
            print(f'CLI argument error - "{args.passwordDictionary}" does not exist')
            sys.exit(1)
        with open(args.passwordDictionary, 'r') as f:
            for line in f:
                password = line.strip()
                if password and test_password(args.inputFile, password, args.fileNumber):
                    elapsed = time.time() - start_time
                    print(f'Time elapsed: {elapsed * 1000:.3f}ms')
                    print(f'Password found:{password}')
                    sys.exit(0)
        print('Password not found')
        sys.exit(1)

    # Brute force attack
    password = find_password_bruteforce(args.inputFile, charset, args.minPasswordLen, args.maxPasswordLen, args.fileNumber)
    elapsed = time.time() - start_time

    if password:
        print(f'Time elapsed: {elapsed * 1000:.3f}ms')
        print(f'Password found:{password}')
        sys.exit(0)
    else:
        print('Password not found')
        sys.exit(1)

if __name__ == '__main__':
    main()
